<script setup lang="ts">
type Side='left'|'right'
type DancerId='a'|'b'
type PhaseName='available'|'proposal'|'projection'|'transfer'|'pivot'|'arrival'
type Embrace='open'|'halfOpen'|'closed'
type Initiator=DancerId|'shared'|'none'
type Articulation='legato'|'marcato'|'staccato'
type Connection='connected'|'separate'
type Foot={x:number;y:number;angle:number;load:number}
type Dancer={torso:{x:number;y:number};angle:number;pelvisAngle:number;left:Foot;right:Foot}
type Pose={id:string;name:string;at:number;duration:number;stanceHeight:number;phase:PhaseName;embrace:Embrace;initiator:Initiator;note:string;a:Dancer;b:Dancer}
type LoadMode='manual'|'suggest'|'auto'
type LoadIssue={fromIndex:number;toIndex:number;id:DancerId;side:Side;travel:number;text:string}
type StoredMovement={id:string;name:string;updatedAt:string;data:any}
type MusicalBinding={phaseId:string;countsAsBeat:boolean;beatUnits:number;articulation:Articulation;connection:Connection}
type MusicalInterpretation={id:string;name:string;bindings:Record<string,MusicalBinding>}

const props=withDefaults(defineProps<{locale?:'nl'|'en'}>(),{locale:'nl'})
const nl=computed(()=>props.locale==='nl')
const clone=<T,>(value:T):T=>JSON.parse(JSON.stringify(value))
const foot=(x:number,y:number,angle:number,load:number):Foot=>({x,y,angle,load})
const dancer=(x:number,y:number,angle:number,left:Foot,right:Foot):Dancer=>({torso:{x,y},angle,pelvisAngle:angle,left,right})
const initial=():Pose[]=>[
 {id:crypto.randomUUID(),name:'',at:0,duration:0,stanceHeight:.5,phase:'available',embrace:'open',initiator:'none',note:'',a:dancer(330,250,0,foot(310,232,0,0),foot(310,268,0,1)),b:dancer(470,250,180,foot(490,268,180,1),foot(490,232,180,0))},
 {id:crypto.randomUUID(),name:'',at:1,duration:1,stanceHeight:.5,phase:'arrival',embrace:'open',initiator:'shared',note:'',a:dancer(330,250,0,foot(310,232,0,1),foot(310,268,0,0)),b:dancer(470,250,180,foot(490,268,180,0),foot(490,232,180,1))}
]
const poses=ref<Pose[]>(initial())
const selected=ref(0)
const progress=ref(0)
const playing=ref(false)
const jsonInput=ref('')
const message=ref('')
const loadMode=ref<LoadMode>('suggest')
const undoPoses=ref<Pose[]|null>(null)
const movementName=ref('')
const figureId=ref(crypto.randomUUID())
const neutralInterpretation=():MusicalInterpretation=>({id:crypto.randomUUID(),name:'',bindings:{}})
const musicalInterpretations=ref<MusicalInterpretation[]>([neutralInterpretation()])
const activeInterpretationId=ref(musicalInterpretations.value[0].id)
const savedMovementId=ref<string|null>(null)
const savedMovements=ref<StoredMovement[]>([])
const activeDancer=ref<DancerId>('b')
const precisionOpen=ref(false)
const canvasZoom=ref(85)
const sessionKey='tango-editor-movements-v1'
let timer:ReturnType<typeof setInterval>|undefined

const phaseLabels:Record<PhaseName,{nl:string;en:string}>={available:{nl:'beschikbaar',en:'available'},proposal:{nl:'voorstel',en:'proposal'},projection:{nl:'projectie',en:'projection'},transfer:{nl:'gewichtsoverdracht',en:'weight transfer'},pivot:{nl:'pivot',en:'pivot'},arrival:{nl:'aankomst',en:'arrival'}}
const phaseIcons:Record<PhaseName,string>={available:'○',proposal:'◇',projection:'→',transfer:'⇄',pivot:'↻',arrival:'●'}
const phaseOptions=Object.keys(phaseLabels) as PhaseName[]
const current=computed(()=>poses.value[selected.value])
const activeInterpretation=computed(()=>musicalInterpretations.value.find(item=>item.id===activeInterpretationId.value)??musicalInterpretations.value[0])
const activeBinding=(phaseId:string)=>{
 const bindings=activeInterpretation.value.bindings
 return bindings[phaseId]??(bindings[phaseId]={phaseId,countsAsBeat:phaseId===poses.value.at(-1)?.id,beatUnits:1,articulation:'legato',connection:'connected'})
}
const timingCurve=(binding:Pick<MusicalBinding,'articulation'|'connection'>,t:number)=>{const u=binding.connection==='separate'?Math.max(0,Math.min(1,(t-.08)/.84)):Math.max(0,Math.min(1,t));if(binding.articulation==='staccato')return Math.min(1,Math.pow(u/.62,.72));if(binding.articulation==='marcato')return 1-Math.pow(1-u,3);return .5-Math.cos(Math.PI*u)/2}
const inverseTimingCurve=(binding:Pick<MusicalBinding,'articulation'|'connection'>,target:number)=>{let low=0,high=1;for(let i=0;i<16;i++){const mid=(low+high)/2;if(timingCurve(binding,mid)<target)low=mid;else high=mid}return(low+high)/2}
const rhythmGroups=computed(()=>{const groups:{startIndex:number;endIndex:number;beatUnits:number;articulation:Articulation;connection:Connection;duration:number;startClock:number;endClock:number}[]=[],last=poses.value.length-1;let start=1;for(let index=1;index<=last;index++){const binding=activeBinding(poses.value[index].id);if(binding.countsAsBeat||index===last){const duration=poses.value.slice(start,index+1).reduce((sum,pose)=>sum+Math.max(.125,pose.duration||1),0);groups.push({startIndex:start,endIndex:index,beatUnits:Math.max(.25,binding.beatUnits||1),articulation:binding.articulation,connection:binding.connection,duration,startClock:0,endClock:0});start=index+1}}const total=groups.reduce((sum,group)=>sum+group.beatUnits,0)||1;let elapsed=0;for(const group of groups){group.startClock=elapsed/total;elapsed+=group.beatUnits;group.endClock=elapsed/total}return groups})
const animationTimeline=computed(()=>poses.value.map((pose,index)=>{if(index===0)return{pose,at:0};const group=rhythmGroups.value.find(item=>index>=item.startIndex&&index<=item.endIndex)!;const elapsed=poses.value.slice(group.startIndex,index+1).reduce((sum,item)=>sum+Math.max(.125,item.duration||1),0),source=elapsed/group.duration;return{pose,at:group.startClock+inverseTimingCurve(group,source)*(group.endClock-group.startClock)}}))
const phaseProgress=(phaseId:string)=>Math.round((animationTimeline.value.find(item=>item.pose.id===phaseId)?.at??0)*100)
const lerp=(a:number,b:number,t:number)=>a+(b-a)*t
const angleLerp=(a:number,b:number,t:number)=>a+(((b-a+540)%360)-180)*t
const interpolateFoot=(a:Foot,b:Foot,t:number):Foot=>({x:lerp(a.x,b.x,t),y:lerp(a.y,b.y,t),angle:angleLerp(a.angle,b.angle,t),load:lerp(a.load,b.load,t)})
const interpolateDancer=(a:Dancer,b:Dancer,t:number):Dancer=>({torso:{x:lerp(a.torso.x,b.torso.x,t),y:lerp(a.torso.y,b.torso.y,t)},angle:angleLerp(a.angle,b.angle,t),pelvisAngle:angleLerp(a.pelvisAngle,b.pelvisAngle,t),left:interpolateFoot(a.left,b.left,t),right:interpolateFoot(a.right,b.right,t)})
const preview=computed(()=>{
 const p=progress.value/100,group=rhythmGroups.value.find(item=>p<=item.endClock+.0001)??rhythmGroups.value.at(-1)!,raw=(p-group.startClock)/Math.max(.001,group.endClock-group.startClock),position=timingCurve(group,raw)*group.duration;let elapsed=0,index=group.startIndex
 for(;index<=group.endIndex;index++){const duration=Math.max(.125,poses.value[index].duration||1);if(position<=elapsed+duration||index===group.endIndex)break;elapsed+=duration}
 const from=poses.value[index-1],to=poses.value[index],t=Math.max(0,Math.min(1,(position-elapsed)/Math.max(.125,to.duration||1)))
 return{...clone(t<.5?from:to),stanceHeight:lerp(from.stanceHeight??.5,to.stanceHeight??.5,t),a:interpolateDancer(from.a,to.a,t),b:interpolateDancer(from.b,to.b,t)}
})
const display=computed(()=>playing.value?preview.value:current.value)
const transform=(x:{x:number;y:number;angle:number})=>`translate(${x.x} ${x.y}) rotate(${x.angle})`
const distance=(a:{x:number;y:number},b:{x:number;y:number})=>Math.hypot(a.x-b.x,a.y-b.y)
const direction=(a:{x:number;y:number},b:{x:number;y:number})=>Math.atan2(b.y-a.y,b.x-a.x)*180/Math.PI
const angleError=(a:number,b:number)=>Math.abs(((a-b+540)%360)-180)
const support=(d:Dancer)=>d.left.load>.75?'left':d.right.load>.75?'right':Math.abs(d.left.load-d.right.load)<.15?'shared':'transitioning'
const bucket=(value:number,limits:number[],labels:string[])=>labels[limits.findIndex(limit=>value<limit)]??labels.at(-1)!
const functionalProfile=(p:Pose)=>{
 const torsoDistance=distance(p.a.torso,p.b.torso),aFacing=angleError(p.a.angle,direction(p.a.torso,p.b.torso)),bFacing=angleError(p.b.angle,direction(p.b.torso,p.a.torso))
 return{phaseType:p.phase,embrace:p.embrace,initiator:p.initiator,support:{a:support(p.a),b:support(p.b)},stanceHeight:bucket(p.stanceHeight,[.34,.67],['low','normal','high']),distance:bucket(torsoDistance,[105,155],['close','medium','far']),facing:aFacing<35&&bFacing<35?'maintained':aFacing<75&&bFacing<75?'offset':'broken'}
}
const phaseSignature=(p:Pose)=>{const f=functionalProfile(p);return`${f.phaseType} · ${f.initiator==='none'?'—':f.initiator.toUpperCase()} → · A:${f.support.a[0].toUpperCase()} B:${f.support.b[0].toUpperCase()} · ${f.embrace} · ${f.distance}/${f.facing} · ${f.stanceHeight}`}
const phaseDisplayName=(p:Pose,index:number)=>p.name.trim()||`${phaseLabels[p.phase][nl.value?'nl':'en']} ${index+1}`
const checks=computed(()=>{
 const x=display.value,separation=distance(x.a.torso,x.b.torso),aFacing=angleError(x.a.angle,direction(x.a.torso,x.b.torso)),bFacing=angleError(x.b.angle,direction(x.b.torso,x.a.torso))
 return[
  {ok:separation>=75&&separation<=205,nl:`Bovenlijfafstand ${Math.round(separation)}`,en:`Upper-body distance ${Math.round(separation)}`},
  {ok:aFacing<=85&&bFacing<=85,nl:`Naar elkaar gericht: afwijking ${Math.round(aFacing)}° / ${Math.round(bFacing)}°`,en:`Mutual orientation: error ${Math.round(aFacing)}° / ${Math.round(bFacing)}°`},
  {ok:(['a','b'] as DancerId[]).every(id=>Math.abs(x[id].left.load+x[id].right.load-1)<.02),nl:'Voetbelasting sluit op 100%',en:'Foot loads sum to 100%'}
 ]
})
const sequenceChecks=computed<LoadIssue[]>(()=>{const issues:LoadIssue[]=[];for(let i=1;i<poses.value.length;i++)for(const id of ['a','b'] as DancerId[])for(const side of ['left','right'] as Side[]){const from=poses.value[i-1][id][side],to=poses.value[i][id][side],travel=distance(from,to);if(from.load>=.85&&to.load>=.85&&travel>4)issues.push({fromIndex:i-1,toIndex:i,id,side,travel,text:nl.value?`Fase ${i}→${i+1}: ${id.toUpperCase()} ${side==='left'?'links':'rechts'} schuift ${Math.round(travel)} terwijl die belast blijft.`:`Phase ${i}→${i+1}: ${id.toUpperCase()} ${side} slides ${Math.round(travel)} while remaining loaded.`})}return issues})
const trace=computed(()=>poses.value.flatMap(p=>{const feet=(['left','right'] as Side[]).filter(s=>p.b[s].load<.25);return feet.map(s=>`${p.b[s].x},${p.b[s].y}`)}).join(' '))

const choose=(index:number)=>{selected.value=index;progress.value=phaseProgress(poses.value[index].id);playing.value=false}
const fitCanvas=()=>{canvasZoom.value=100}
const recalculateTimes=()=>{const total=poses.value.slice(1).reduce((sum,p)=>sum+Math.max(.25,p.duration||1),0);let elapsed=0;poses.value.forEach((p,index)=>{if(index===0){p.at=0;p.duration=0}else{elapsed+=Math.max(.25,p.duration||1);p.at=elapsed/total}})}
const duplicate=()=>{const sourceIndex=selected.value,source=clone(current.value),wasLast=sourceIndex===poses.value.length-1;source.id=crypto.randomUUID();source.duration=1;poses.value.splice(sourceIndex+1,0,source);for(const interpretation of musicalInterpretations.value){const original=activeBindingFor(interpretation,poses.value[sourceIndex].id);interpretation.bindings[source.id]={...clone(original),phaseId:source.id,countsAsBeat:wasLast?original.countsAsBeat:false};if(wasLast&&original.countsAsBeat)interpretation.bindings[poses.value[sourceIndex].id]={...clone(original),countsAsBeat:false}}selected.value++;recalculateTimes();choose(selected.value)}
const ensureFinalRhythmMarker=()=>{const finalId=poses.value.at(-1)?.id;if(!finalId)return;for(const interpretation of musicalInterpretations.value){const hasMarker=poses.value.slice(1).some(p=>interpretation.bindings[p.id]?.countsAsBeat);if(!hasMarker)interpretation.bindings[finalId]={...activeBindingFor(interpretation,finalId),countsAsBeat:true}}}
const remove=()=>{if(poses.value.length<=2)return;const [removed]=poses.value.splice(selected.value,1);for(const interpretation of musicalInterpretations.value)delete interpretation.bindings[removed.id];ensureFinalRhythmMarker();selected.value=Math.min(selected.value,poses.value.length-1);recalculateTimes()}
const updateDuration=()=>{recalculateTimes();progress.value=phaseProgress(current.value.id)}
const remember=()=>{undoPoses.value=clone(poses.value)}
const undo=()=>{if(!undoPoses.value)return;poses.value=undoPoses.value;undoPoses.value=null;message.value=nl.value?'Laatste correctie ongedaan gemaakt':'Last correction undone'}
const inferLoad=(issue:Pick<LoadIssue,'fromIndex'|'toIndex'|'id'|'side'>,rememberFirst=true)=>{if(rememberFirst)remember();const other:Side=issue.side==='left'?'right':'left';for(const index of [issue.fromIndex,issue.toIndex]){poses.value[index][issue.id][issue.side].load=0;poses.value[index][issue.id][other].load=1}message.value=nl.value?'Belasting gecorrigeerd; de bewegende voet is vrijgemaakt.':'Load corrected; the moving foot was made free.'}
const setLoad=(id:DancerId,side:Side,value:number)=>{const load=Math.max(0,Math.min(1,Number(value))),other:Side=side==='left'?'right':'left';current.value[id][side].load=load;current.value[id][other].load=Number((1-load).toFixed(2))}
const restoreFoot=(issue:LoadIssue)=>{remember();const from=poses.value[issue.fromIndex][issue.id][issue.side],to=poses.value[issue.toIndex][issue.id][issue.side];Object.assign(to,{x:from.x,y:from.y,angle:from.angle});message.value=nl.value?'De standvoet is naar zijn vorige positie hersteld.':'The support foot was restored to its previous position.'}
const autoCorrectAll=()=>{const issues=[...sequenceChecks.value];if(!issues.length)return;remember();for(const issue of issues)inferLoad(issue,false);message.value=nl.value?`${issues.length} belastingsconflict(en) automatisch gecorrigeerd.`:`${issues.length} load conflict(s) corrected automatically.`}
watch(loadMode,mode=>{if(mode==='auto')autoCorrectAll()})
onMounted(()=>{const saved=localStorage.getItem('tango-editor-load-mode') as LoadMode|null;if(saved&&['manual','suggest','auto'].includes(saved))loadMode.value=saved;try{const collection=JSON.parse(sessionStorage.getItem(sessionKey)||'[]');if(Array.isArray(collection))savedMovements.value=collection}catch{sessionStorage.removeItem(sessionKey)}})
watch(loadMode,mode=>{if(import.meta.client)localStorage.setItem('tango-editor-load-mode',mode)})
const togglePlay=()=>{if(progress.value>=100)progress.value=0;playing.value=!playing.value}
watch(playing,on=>{if(timer)clearInterval(timer);if(!on)return;timer=setInterval(()=>{progress.value=Math.min(100,progress.value+.6);if(progress.value>=100)playing.value=false},30)})
onBeforeUnmount(()=>{if(timer)clearInterval(timer)})

type DragTarget={id:DancerId;part:'torso'|Side;start:{x:number;y:number};pointer:{x:number;y:number}}
const drag=ref<DragTarget|null>(null)
const svg=ref<SVGSVGElement>()
const svgPoint=(event:PointerEvent)=>{const box=svg.value!.getBoundingClientRect();return{x:80+(event.clientX-box.left)/box.width*640,y:70+(event.clientY-box.top)/box.height*360}}
const startDrag=(event:PointerEvent,id:DancerId,part:'torso'|Side)=>{if(playing.value)return;activeDancer.value=id;if(part!=='torso')precisionOpen.value=true;const p=svgPoint(event),target=part==='torso'?current.value[id].torso:current.value[id][part];if(part!=='torso'&&loadMode.value==='auto')remember();drag.value={id,part,start:{x:target.x,y:target.y},pointer:p};(event.currentTarget as Element).setPointerCapture(event.pointerId)}
const moveDrag=(event:PointerEvent)=>{if(!drag.value)return;const p=svgPoint(event),dx=p.x-drag.value.pointer.x,dy=p.y-drag.value.pointer.y,target=drag.value.part==='torso'?current.value[drag.value.id].torso:current.value[drag.value.id][drag.value.part];target.x=Math.round(drag.value.start.x+dx);target.y=Math.round(drag.value.start.y+dy)}
const stopDrag=()=>{const completed=drag.value;drag.value=null;if(!completed||completed.part==='torso'||loadMode.value!=='auto'||selected.value===0)return;const travel=distance(poses.value[selected.value-1][completed.id][completed.part],poses.value[selected.value][completed.id][completed.part]);if(travel>4)inferLoad({fromIndex:selected.value-1,toIndex:selected.value,id:completed.id,side:completed.part},false)}

const snap=(value:number,step:number)=>Math.round(value/step)*step
const quantise=(level:'fine'|'medium'|'coarse')=>{const settings={fine:{position:5,angle:5,load:.05,height:.05},medium:{position:10,angle:15,load:.1,height:.25},coarse:{position:20,angle:45,load:.5,height:.5}}[level];for(const pose of poses.value){pose.stanceHeight=Math.max(0,Math.min(1,snap(pose.stanceHeight,settings.height)));for(const id of ['a','b'] as DancerId[]){const d=pose[id];d.torso.x=snap(d.torso.x,settings.position);d.torso.y=snap(d.torso.y,settings.position);d.angle=snap(d.angle,settings.angle);d.pelvisAngle=snap(d.pelvisAngle,settings.angle);for(const side of ['left','right'] as Side[]){d[side].x=snap(d[side].x,settings.position);d[side].y=snap(d[side].y,settings.position);d[side].angle=snap(d[side].angle,settings.angle);d[side].load=Math.max(0,Math.min(1,snap(d[side].load,settings.load)))}const sum=d.left.load+d.right.load;if(sum){d.left.load=Number((d.left.load/sum).toFixed(2));d.right.load=Number((1-d.left.load).toFixed(2))}}}message.value=nl.value?`Alle fasen zijn ${level==='fine'?'fijn':level==='medium'?'middelgrof':'grof'} uitgelijnd`:`All phases snapped to the ${level} grid`}
const addInterpretation=()=>{const item=neutralInterpretation();item.name=nl.value?`Interpretatie ${musicalInterpretations.value.length+1}`:`Interpretation ${musicalInterpretations.value.length+1}`;musicalInterpretations.value.push(item);activeInterpretationId.value=item.id}
const duplicateInterpretation=()=>{const item=clone(activeInterpretation.value);item.id=crypto.randomUUID();item.name=`${item.name|| (nl.value?'Neutraal':'Neutral')} — ${nl.value?'variant':'variant'}`;musicalInterpretations.value.push(item);activeInterpretationId.value=item.id}
const removeInterpretation=()=>{if(musicalInterpretations.value.length<=1)return;musicalInterpretations.value=musicalInterpretations.value.filter(item=>item.id!==activeInterpretationId.value);activeInterpretationId.value=musicalInterpretations.value[0].id}
const payload=()=>({
 format:'tango-figure',version:6,
 coordinateSystem:{view:'top',origin:'stage',angleDegrees:'clockwise',units:'model',stanceHeight:'0=low, 0.5=neutral, 1=extended'},
 figure:{id:figureId.value,name:movementName.value.trim()||undefined,entryPhaseId:poses.value[0]?.id,phaseIds:poses.value.map(p=>p.id)},
 phases:poses.value.map((p,index)=>({id:p.id,name:phaseDisplayName(p,index),type:p.phase,relativeDuration:p.duration,note:p.note,configuration:{dancers:{a:clone(p.a),b:clone(p.b)},relationship:{embrace:p.embrace,torsoDistance:Number(distance(p.a.torso,p.b.torso).toFixed(2))},dynamics:{initiator:p.initiator},stanceHeight:p.stanceHeight},functionalProfile:functionalProfile(p),signature:phaseSignature(p)})),
 musicalInterpretations:musicalInterpretations.value.map(item=>({id:item.id,name:item.name||undefined,phaseBindings:poses.value.slice(1).map(p=>clone(activeBindingFor(item,p.id)))}))
})
const activeBindingFor=(interpretation:MusicalInterpretation,phaseId:string)=>interpretation.bindings[phaseId]??{phaseId,countsAsBeat:phaseId===poses.value.at(-1)?.id,beatUnits:1,articulation:'legato' as Articulation,connection:'connected' as Connection}
const persistMovements=()=>{sessionStorage.setItem(sessionKey,JSON.stringify(savedMovements.value));window.dispatchEvent(new CustomEvent('tango-editor-movements-changed'))}
const loadSequence=(incoming:any[])=>{if(!Array.isArray(incoming)||incoming.length<2)throw new Error('phases');poses.value=incoming.map((p,index)=>({...p,id:p.id??crypto.randomUUID(),name:p.name??'',embrace:p.embrace??'open',initiator:p.initiator??'none',stanceHeight:p.stanceHeight??.5,duration:index===0?0:(p.duration??p.relativeDuration??Math.max(.25,(p.at-(incoming[index-1]?.at??0))*incoming.length))}));selected.value=0;progress.value=0;playing.value=false;recalculateTimes()}
const loadFigure=(data:any)=>{if(data?.format!=='tango-figure'||!Array.isArray(data.phases))throw new Error('figure');const ordered=(data.figure?.phaseIds??data.phases.map((p:any)=>p.id)).map((id:string)=>data.phases.find((p:any)=>p.id===id)).filter(Boolean);loadSequence(ordered.map((p:any)=>({id:p.id,name:p.name,type:p.type,phase:p.type,duration:p.relativeDuration,note:p.note??'',stanceHeight:p.configuration?.stanceHeight??.5,embrace:p.configuration?.relationship?.embrace??'open',initiator:p.configuration?.dynamics?.initiator??'none',a:p.configuration?.dancers?.a,b:p.configuration?.dancers?.b})));figureId.value=data.figure?.id??crypto.randomUUID();movementName.value=data.figure?.name??data.name??'';musicalInterpretations.value=Array.isArray(data.musicalInterpretations)&&data.musicalInterpretations.length?data.musicalInterpretations.map((item:any)=>{const list=item.phaseBindings??[];return{id:item.id??crypto.randomUUID(),name:item.name??'',bindings:Object.fromEntries(list.map((binding:any,index:number)=>[binding.phaseId,{phaseId:binding.phaseId,countsAsBeat:binding.countsAsBeat??index===list.length-1,beatUnits:binding.beatUnits??1,articulation:binding.articulation??'legato',connection:binding.connection??'connected'}]))}}):[neutralInterpretation()];activeInterpretationId.value=musicalInterpretations.value[0].id}
const newMovement=()=>{poses.value=initial();figureId.value=crypto.randomUUID();musicalInterpretations.value=[neutralInterpretation()];activeInterpretationId.value=musicalInterpretations.value[0].id;selected.value=0;progress.value=0;playing.value=false;movementName.value='';savedMovementId.value=null;undoPoses.value=null;jsonInput.value='';message.value=nl.value?'Nieuwe lege figuur gestart':'New blank figure started'}
const saveMovement=()=>{const name=movementName.value.trim();if(!name){message.value=nl.value?'Geef de beweging eerst een naam.':'Name the movement first.';return}const id=savedMovementId.value??crypto.randomUUID(),entry:StoredMovement={id,name,updatedAt:new Date().toISOString(),data:payload()};const index=savedMovements.value.findIndex(item=>item.id===id);if(index<0)savedMovements.value.push(entry);else savedMovements.value[index]=entry;savedMovementId.value=id;movementName.value=name;persistMovements();message.value=nl.value?'Beweging in deze sessie opgeslagen':'Movement saved in this session'}
const loadMovement=(id:string)=>{const entry=savedMovements.value.find(item=>item.id===id);if(!entry)return;if(entry.data.format==='tango-figure')loadFigure(entry.data);else loadSequence(entry.data.poses);savedMovementId.value=id;movementName.value=entry.name;message.value=nl.value?`‘${entry.name}’ geladen`:`‘${entry.name}’ loaded`}
const deleteMovement=(id:string)=>{savedMovements.value=savedMovements.value.filter(item=>item.id!==id);if(savedMovementId.value===id)newMovement();persistMovements();message.value=nl.value?'Opgeslagen beweging verwijderd':'Saved movement removed'}
const copyJson=async()=>{await navigator.clipboard.writeText(JSON.stringify(payload(),null,2));message.value=nl.value?'JSON gekopieerd':'JSON copied'}
const download=(data:unknown,filename:string)=>{const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();URL.revokeObjectURL(url)}
const slug=(value:string)=>value.toLowerCase().trim().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')
const downloadJson=()=>download({...payload(),name:movementName.value.trim()||undefined},`${slug(movementName.value)||'tango-bewegingssequentie'}.json`)
const exportSet=()=>download({format:'tango-figure-set',version:2,exportedAt:new Date().toISOString(),figures:savedMovements.value.map(({name,data})=>({name,...data}))},'tango-figurenset.json')
const importJson=()=>{try{const parsed=JSON.parse(jsonInput.value);if((parsed.format==='tango-figure-set'||parsed.format==='tango-movement-set')&&Array.isArray(parsed.figures??parsed.movements)){const items=parsed.figures??parsed.movements;const imported:StoredMovement[]=items.map((item:any)=>{if(item.format!=='tango-figure'&&(!Array.isArray(item.poses)||item.poses.length<2))throw new Error('phases');const name=item.figure?.name??item.name??'Naamloze figuur';return{id:crypto.randomUUID(),name:String(name),updatedAt:new Date().toISOString(),data:item}});savedMovements.value=[...savedMovements.value,...imported];persistMovements();message.value=nl.value?`${imported.length} figuur/figuren aan de sessie toegevoegd`:`${imported.length} figure(s) added to the session`;return}if(parsed.format==='tango-figure')loadFigure(parsed);else{const incoming=Array.isArray(parsed)?parsed:parsed.poses;loadSequence(incoming);movementName.value=parsed.name??'';figureId.value=crypto.randomUUID()}savedMovementId.value=null;message.value=nl.value?'Figuur geladen':'Figure loaded'}catch{message.value=nl.value?'Ongeldige JSON':'Invalid JSON'}}
</script>

<template>
 <section class="pose-editor">
  <header><p class="eyebrow">{{nl?'TANGOFIGUUR-EDITOR':'TANGO FIGURE EDITOR'}}</p><h3>{{nl?'Modelleer de figuur fase voor fase':'Model the figure phase by phase'}}</h3><p>{{nl?'Iedere fase beschrijft de gezamenlijke configuratie van beide dansers, hun abrazo en de actuele initiatiefverdeling. De editor berekent de beweging tussen die fases.':'Each phase describes the joint configuration of both dancers, their embrace and the current distribution of initiative. The editor calculates the movement between those phases.'}}</p></header>
  <section class="movement-workspace">
   <label class="movement-name"><span>{{nl?'Figuur':'Figure'}}</span><input v-model="movementName" type="text" :placeholder="nl?'Naam figuur':'Figure name'"></label>
   <button class="save" @click="saveMovement">{{savedMovementId?(nl?'Opslaan':'Save changes'):(nl?'Bewaren':'Save')}}</button><button @click="newMovement">+ {{nl?'Nieuw':'New'}}</button>
   <select :value="savedMovementId??''" :aria-label="nl?'Open opgeslagen beweging':'Open saved movement'" @change="loadMovement(($event.target as HTMLSelectElement).value)"><option value="" disabled>{{savedMovements.length?(nl?'Open beweging…':'Open movement…'):(nl?'Nog niets bewaard':'Nothing saved yet')}}</option><option v-for="item in savedMovements" :key="item.id" :value="item.id">{{item.name}}</option></select>
   <details class="workspace-menu"><summary :aria-label="nl?'Meer acties':'More actions'">•••</summary><div><button :disabled="!savedMovementId" @click="savedMovementId&&deleteMovement(savedMovementId)">{{nl?'Huidige verwijderen':'Delete current'}}</button><button :disabled="!savedMovements.length" @click="exportSet">{{nl?'Set exporteren':'Export set'}}</button><small>{{nl?'Beschikbaar zolang dit tabblad open is.':'Available while this tab stays open.'}}</small></div></details>
  </section>
  <div class="editor-grid">
   <div class="canvas-column">
   <div class="canvas-card">
    <div class="canvas-toolbar"><button @click="togglePlay">{{playing?'Ⅱ':'▶'}} {{playing?(nl?'Pauze':'Pause'):(nl?'Animeer':'Animate')}}</button><label>{{nl?'tijd':'time'}} <input v-model.number="progress" type="range" min="0" max="100"></label><output>{{Math.round(progress)}}%</output><div class="zoom"><button :disabled="canvasZoom<=60" @click="canvasZoom=Math.max(60,canvasZoom-10)">−</button><label :title="nl?'Weergavezoom; verandert modelcoördinaten niet':'View zoom; does not change model coordinates'"><input v-model.number="canvasZoom" type="range" min="60" max="140" step="5"><span>{{canvasZoom}}%</span></label><button :disabled="canvasZoom>=140" @click="canvasZoom=Math.min(140,canvasZoom+10)">+</button><button @click="fitCanvas">{{nl?'Passend':'Fit'}}</button></div></div>
    <div class="canvas-viewport"><svg ref="svg" viewBox="80 70 640 360" :style="{width:`${canvasZoom}%`}" @pointermove="moveDrag" @pointerup="stopDrag" @pointercancel="stopDrag">
     <rect x="80" y="70" width="640" height="360" rx="20" class="floor"/><line :x1="display.a.torso.x" :y1="display.a.torso.y" :x2="display.b.torso.x" :y2="display.b.torso.y" class="embrace-axis"/>
     <polyline v-if="trace" :points="trace" class="trace"/>
     <g v-for="id in (['a','b'] as DancerId[])" :key="id" :class="['dancer',`dancer-${id}`]">
      <g v-for="side in (['left','right'] as Side[])" :key="side" :transform="transform(display[id][side])" class="foot" @pointerdown="startDrag($event,id,side)"><circle r="25" :style="{opacity:.08+display[id][side].load*.28}"/><path d="M-21-9H8Q25 0 8 9H-21Q-27 0-21-9Z"/><text y="4">{{side==='left'?'L':'R'}}</text></g>
      <g :transform="transform({...display[id].torso,angle:display[id].pelvisAngle})" class="pelvis"><path d="M-5-16Q4-23 13-16L13 16Q4 23-5 16Z"/></g>
      <g :transform="`${transform({...display[id].torso,angle:display[id].angle})} scale(${.9+display.stanceHeight*.2})`" class="torso" @pointerdown="startDrag($event,id,'torso')"><path d="M-8-31C8-42 28-38 42-24L42 24C28 38 8 42-8 31Z"/><path class="gaze" d="M15 0H34M27-6 34 0 27 6"/><text x="5" y="5">{{id.toUpperCase()}}</text></g>
     </g>
    </svg></div>
    <p class="hint">{{nl?'Sleep de bovenlijven en voeten. De stippellijn toont de verbinding; de dunne lijn volgt geprojecteerde vrije voeten van B.':'Drag upper bodies and feet. The dashed line shows the connection; the thin line follows B’s projected free feet.'}}</p>
   </div>
   <div class="status-bar"><button v-for="check in checks" :key="check.nl" :class="{ok:check.ok}" :title="nl?check.nl:check.en">{{check.ok?'✓':'!'}} <span>{{nl?check.nl.split(':')[0]:check.en.split(':')[0]}}</span></button><button :class="{ok:!sequenceChecks.length}" :title="sequenceChecks.map(item=>item.text).join('\n')">{{sequenceChecks.length?'!':'✓'}} <span>{{nl?'standvoet':'support foot'}}</span></button></div>
   </div>
   <aside class="controls">
    <div class="phase-tabs"><button v-for="(pose,index) in poses" :key="pose.id" :class="['phase-'+pose.phase,{active:index===selected}]" :title="`${phaseDisplayName(pose,index)}: ${pose.note||'—'}`" @click="choose(index)"><span>{{index+1}}</span><b>{{phaseIcons[pose.phase]}}</b><small>{{phaseProgress(pose.id)}}%</small></button></div>
    <div class="phase-actions"><button @click="duplicate">+ {{nl?'fase dupliceren':'duplicate phase'}}</button><button :disabled="poses.length<=2" @click="remove">{{nl?'verwijderen':'remove'}}</button></div>
    <label>{{nl?'Relatieve duur':'Relative duration'}} <input v-model.number="current.duration" type="range" min=".25" max="3" step=".25" :disabled="selected===0" @input="updateDuration"><output>{{selected===0?'—':`${current.duration}×`}}</output></label>
    <label>{{nl?'Naam':'Name'}} <input v-model="current.name" type="text" :placeholder="phaseDisplayName(current,selected)"></label>
    <label>{{nl?'Fasetype':'Phase type'}} <select v-model="current.phase"><option v-for="name in phaseOptions" :key="name" :value="name">{{phaseIcons[name]}} {{phaseLabels[name][nl?'nl':'en']}}</option></select></label>
    <label>{{nl?'Abrazo':'Embrace'}} <select v-model="current.embrace"><option value="open">{{nl?'open':'open'}}</option><option value="halfOpen">{{nl?'halfopen':'half-open'}}</option><option value="closed">{{nl?'gesloten':'closed'}}</option></select></label>
    <label>{{nl?'Initiatief':'Initiative'}} <select v-model="current.initiator"><option value="none">{{nl?'geen / beschikbaar':'none / available'}}</option><option value="a">A</option><option value="b">B</option><option value="shared">{{nl?'gedeeld':'shared'}}</option></select></label>
    <div class="shared-height"><strong>{{nl?'Basishouding':'Base stance'}}</strong><input v-model.number="current.stanceHeight" type="range" min="0" max="1" step=".05"><div><span>{{nl?'laag':'low'}}</span><b>{{nl?'normaal':'normal'}}</b><span>{{nl?'hoog':'high'}}</span></div><output>{{Math.round(current.stanceHeight*100)}}%</output></div>
    <label>{{nl?'Notitie':'Note'}} <input v-model="current.note" type="text"></label>
    <div class="phase-identity"><small>{{nl?'Fase-ID':'Phase ID'}} · {{current.id}}</small><strong>{{phaseSignature(current)}}</strong></div>
    <div class="dancer-tabs"><button v-for="id in (['a','b'] as DancerId[])" :key="id" :class="{active:activeDancer===id}" @click="activeDancer=id"><strong>{{id==='a'?(nl?'Leider A':'Leader A'):(nl?'Volger B':'Follower B')}}</strong><small>L {{Math.round(current[id].left.load*100)}}% · R {{Math.round(current[id].right.load*100)}}%</small></button></div>
    <div class="angle-grid"><AngleDial v-model="current[activeDancer].angle" :label="nl?'bovenlijf':'upper body'"/><AngleDial v-model="current[activeDancer].pelvisAngle" :label="nl?'bekken':'pelvis'"/></div>
    <div class="quick-load"><label v-for="side in (['left','right'] as Side[])" :key="side"><span>{{side==='left'?(nl?'Links':'Left'):(nl?'Rechts':'Right')}}</span><input :value="current[activeDancer][side].load" type="range" min="0" max="1" step=".05" @input="setLoad(activeDancer,side,Number(($event.target as HTMLInputElement).value))"><output>{{Math.round(current[activeDancer][side].load*100)}}%</output></label></div>
    <details class="precision" :open="precisionOpen" @toggle="precisionOpen=($event.currentTarget as HTMLDetailsElement).open"><summary>{{nl?'Precieze voetinstellingen':'Precise foot settings'}}</summary><div v-for="side in (['left','right'] as Side[])" :key="side" class="foot-controls"><strong>{{side==='left'?(nl?'Linkervoet':'Left foot'):(nl?'Rechtervoet':'Right foot')}}</strong><label>x <input v-model.number="current[activeDancer][side].x" type="number"></label><label>y <input v-model.number="current[activeDancer][side].y" type="number"></label><AngleDial v-model="current[activeDancer][side].angle" :label="nl?'voetrichting':'foot direction'"/></div></details>
    <details class="validation" :open="sequenceChecks.length>0"><summary>{{nl?'Controle en voetbelasting':'Validation and foot load'}} <span :class="{ok:!sequenceChecks.length}">{{sequenceChecks.length||'✓'}}</span></summary><fieldset class="load-mode"><legend>{{nl?'Correctiemodus':'Correction mode'}}</legend><label v-for="mode in (['manual','suggest','auto'] as LoadMode[])" :key="mode"><input v-model="loadMode" type="radio" :value="mode">{{mode==='manual'?(nl?'handmatig':'manual'):mode==='suggest'?(nl?'voorstellen':'suggest'):(nl?'automatisch':'automatic')}}</label><button v-if="undoPoses" @click="undo">↶ {{nl?'ongedaan':'undo'}}</button></fieldset><div class="sequence-check"><p v-if="!sequenceChecks.length" class="ok">✓ {{nl?'Geen schuivende standvoet gevonden.':'No sliding support foot found.'}}</p><ul v-else><li v-for="issue in sequenceChecks" :key="`${issue.toIndex}-${issue.id}-${issue.side}`"><span>! {{issue.text}}</span><div v-if="loadMode!=='manual'"><button @click="inferLoad(issue)">{{nl?'Maak voet vrij':'Make foot free'}}</button><button @click="restoreFoot(issue)">{{nl?'Herstel voet':'Restore foot'}}</button></div></li></ul><button v-if="loadMode==='auto'&&sequenceChecks.length" @click="autoCorrectAll">{{nl?'Alles corrigeren':'Correct all'}}</button></div></details>
   </aside>
  </div>
  <section class="body-model-card">
   <div><p class="eyebrow">{{nl?'LICHAAMSMODEL':'BODY MODEL'}}</p><h4>{{nl?'Geometrische controle van de bewerkbare fase':'Geometric validation of the editable phase'}}</h4><p>{{nl?'Deze toets gebruikt de gezamenlijke configuratie van beide dansers. Hij controleert onder meer onderlinge afstand, oriëntatie, voetbelasting en of een belaste voet tussen twee fases verschuift.':'This validation uses the joint configuration of both dancers. It checks mutual distance, orientation, foot load and whether a loaded foot slides between phases.'}}</p></div>
   <ul><li v-for="check in checks" :key="check.nl" :class="{ok:check.ok}"><span>{{check.ok?'✓':'!'}}</span>{{nl?check.nl:check.en}}</li><li :class="{ok:!sequenceChecks.length}"><span>{{sequenceChecks.length?'!':'✓'}}</span>{{sequenceChecks.length?(nl?`${sequenceChecks.length} conflict(en) met een schuivende standvoet`:`${sequenceChecks.length} sliding support-foot conflict(s)`):(nl?'Geen schuivende standvoet gevonden':'No sliding support foot found')}}</li></ul>
   <strong :class="['validation-result',{ok:checks.every(check=>check.ok)&&!sequenceChecks.length}]">{{checks.every(check=>check.ok)&&!sequenceChecks.length?(nl?'Fase fysiek consistent binnen dit 2D-model':'Phase physically consistent within this 2D model'):(nl?'Fase vraagt controle of correctie':'Phase requires review or correction')}}</strong>
   <small>{{nl?'De controle voorkomt een deel van de geometrisch onmogelijke bewegingen, maar vervangt geen volledig 3D-biomechanisch of medisch model.':'The validation prevents some geometrically impossible movements, but does not replace a complete 3D biomechanical or medical model.'}}</small>
  </section>
  <details class="musical-layer" open>
   <summary>{{nl?'Muzikale interpretaties':'Musical interpretations'}} <small>{{nl?'dezelfde figuur, anders gefraseerd':'the same figure, phrased differently'}}</small></summary>
   <div class="interpretation-toolbar">
    <label><span>{{nl?'Interpretatie':'Interpretation'}}</span><select v-model="activeInterpretationId"><option v-for="item in musicalInterpretations" :key="item.id" :value="item.id">{{item.name||(nl?'Neutraal':'Neutral')}}</option></select></label>
    <label class="interpretation-name"><span>{{nl?'Naam':'Name'}}</span><input v-model="activeInterpretation.name" type="text" :placeholder="nl?'Bijvoorbeeld: scherp en ritmisch':'For example: sharp and rhythmic'"></label>
    <button @click="addInterpretation">+ {{nl?'nieuw':'new'}}</button><button @click="duplicateInterpretation">{{nl?'dupliceer':'duplicate'}}</button><button :disabled="musicalInterpretations.length<=1" @click="removeInterpretation">{{nl?'verwijder':'remove'}}</button>
   </div>
   <p>{{nl?'Deze laag verandert de gezamenlijke fases niet. Markeer alleen de fase die een ritmische tel afsluit: alle voorafgaande, ongemarkeerde fases vormen dan samen met die fase één vloeiende beweging binnen die tel. Lengte, articulatie en verbinding gelden voor die hele beweging. Concrete muziek kan later als afzonderlijke laag worden gekoppeld.':'This layer does not change the joint phases. Mark only the phase that closes a rhythmic beat: all preceding unmarked phases then form one fluid movement within that beat. Length, articulation and connection apply to that whole movement. Concrete music can later be attached as a separate layer.'}}</p>
   <div class="musical-grid">
    <div class="musical-head"><span>{{nl?'Fase':'Phase'}}</span><span>{{nl?'Ritme':'Rhythm'}}</span><span>{{nl?'Lengte':'Length'}}</span><span>{{nl?'Articulatie':'Articulation'}}</span><span>{{nl?'Verbinding':'Connection'}}</span></div>
    <div v-for="(pose,index) in poses.slice(1)" :key="pose.id" class="musical-row">
     <strong>{{index+2}} · {{phaseDisplayName(pose,index+1)}}</strong>
     <label class="beat-marker"><input v-model="activeBinding(pose.id).countsAsBeat" type="checkbox"><span>{{activeBinding(pose.id).countsAsBeat?(nl?'sluit tel af':'closes beat'):(nl?'binnen tel':'within beat')}}</span></label>
     <label><input v-model.number="activeBinding(pose.id).beatUnits" type="range" min=".25" max="4" step=".25" :disabled="!activeBinding(pose.id).countsAsBeat"><output>{{activeBinding(pose.id).countsAsBeat?`${activeBinding(pose.id).beatUnits} ${nl?'tel':'beat'}`:'—'}}</output></label>
     <select v-model="activeBinding(pose.id).articulation"><option value="legato">legato</option><option value="marcato">marcato</option><option value="staccato">staccato</option></select>
     <select v-model="activeBinding(pose.id).connection"><option value="connected">{{nl?'verbonden':'connected'}}</option><option value="separate">{{nl?'los':'separate'}}</option></select>
    </div>
   </div>
  </details>
  <details class="advanced"><summary>{{nl?'Geavanceerd, normaliseren en delen':'Advanced, normalise and share'}}</summary><div class="advanced-grid"><section><h4>{{nl?'Handwerk normaliseren':'Normalise manual input'}}</h4><p>{{nl?'Lijn alle fasen trapsgewijs uit en normaliseer de belasting tot 100%.':'Snap all phases in stages and normalise loads to 100%.'}}</p><button @click="quantise('fine')">{{nl?'Fijn':'Fine'}}</button><button @click="quantise('medium')">{{nl?'Middel':'Medium'}}</button><button @click="quantise('coarse')">{{nl?'Grof':'Coarse'}}</button></section><section><h4>{{nl?'Huidige beweging delen':'Share current movement'}}</h4><button @click="copyJson">{{nl?'Kopieer JSON':'Copy JSON'}}</button><button @click="downloadJson">{{nl?'Download':'Download'}}</button><button :disabled="!savedMovements.length" @click="exportSet">{{nl?'Download set':'Download set'}}</button></section><section><h4>{{nl?'Beweging of set importeren':'Import movement or set'}}</h4><textarea v-model="jsonInput" rows="6" spellcheck="false"/><button @click="importJson">{{nl?'Importeren':'Import'}}</button></section></div></details>
  <details class="model-status">
   <summary>{{nl?'Over de simulator: model, beperkingen en bronnen':'About the simulator: model, limitations and sources'}}</summary>
   <p>{{nl?'De simulator en editor modelleren standbeen, vrije voet, projectie, plaatsing, gewichtsoverdracht, pivot, voet- en schouderoriëntatie, contact, omhelzingsafstand, initiatief en vertraagde respons als afzonderlijke toestanden. Het is een onderzoekbare schematisering, geen dansinstructie of volledig 3D-biomechanisch model.':'The simulator and editor represent supporting leg, free foot, projection, placement, weight transfer, pivot, foot and shoulder orientation, contact, embrace distance, initiative and delayed response as separate states. It is an explorable schematic, not dance instruction or a complete 3D biomechanical model.'}}</p>
   <ul>
    <li><a href="https://www.degruyter.com/document/doi/10.1515/cogsem.2012.4.1.76/html" target="_blank" rel="noopener">Kimmel — Intersubjectivity at Close Quarters</a>: {{nl?'basis voor tango als wederzijdse, belichaamde coördinatie.':'basis for tango as reciprocal, embodied coordination.'}}</li>
    <li><a href="https://www.researchgate.net/publication/334694663_Tango_Ocho_-_1_Functional_Anatomical_Characteristics_of_Dissociation_and_the_Tango_Pivot" target="_blank" rel="noopener">Noh — Tango Ocho</a>: {{nl?'anatomische beschrijving van dissociatie en pivot.':'anatomical account of dissociation and pivot.'}}</li>
    <li><a href="https://tangolife.london/blog/the-molinete-and-giro-circular-movement-in-tango" target="_blank" rel="noopener">TangoLife — The Molinete and Giro</a>: {{nl?'praktijkbron voor de cyclische reeks achter–zij–voor–zij.':'practice source for the back–side–forward–side cycle.'}}</li>
    <li><a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC13453143/" target="_blank" rel="noopener">Torres et al. — Energetics, kinematics, and physiologic aspects of tango walking</a>: {{nl?'3D-onderzoek naar onder meer zwaartepunttrajecten en knieflexie.':'3D research including centre-of-mass trajectories and knee flexion.'}}</li>
   </ul>
  </details>
  <p class="editor-message" role="status">{{message}}</p>
 </section>
</template>

